diff --git a/src/middleware/cors/index.test.ts b/src/middleware/cors/index.test.ts
index f5f5f5f..a6a6a6a 100644
--- a/src/middleware/cors/index.test.ts
+++ b/src/middleware/cors/index.test.ts
@@ -155,6 +155,15 @@ describe('CORS middleware', () => {
     expect(res.headers.get('Access-Control-Allow-Origin')).toBe('https://app.example.com');
   });

+  it('appends Vary: Origin for dynamic origin callback matches', async () => {
+    const app = new Hono();
+    app.use('*', cors({ origin: (o) => (o.endsWith('.example.com') ? o : '') }));
+    app.get('/data', (c) => c.json({ ok: true }));
+    const res = await app.request('/data', { headers: { Origin: 'https://web.example.com' } });
+    expect(res.headers.get('Access-Control-Allow-Origin')).toBe('https://web.example.com');
+    expect(res.headers.get('Vary')).toContain('Origin');
+  });
 });

